mapper.select:
SELECT 

FROM product_profit_distribution_guide g

    g.delflag = 0

        AND g.product_name LIKE CONCAT('%', #{params.productName}, '%')


        AND g.role = #{params.role}


        AND g.commission_type = #{params.commissionType}




        ORDER BY ${params.sortField} ${params.sortOrder}


        ORDER BY g.created_at DESC
